const wsUrl="wss://sdex-alb-664814673.ap-southeast-2.elb.amazonaws.com/ws",ws=new WebSocket(wsUrl);ws.onopen=()=>{console.log("Connected to WebSocket"),document.getElementById("status").textContent="Connected to WebSocket",ws.send(JSON.stringify({type:"subscribe",channel:"orders"}))},ws.onmessage=e=>{console.log("Received:",e.data),"orderBook"===JSON.parse(e.data).type&&(document.getElementById("status").textContent="Order book received")},ws.onerror=e=>{console.error("WebSocket error:",e),document.getElementById("status").textContent="WebSocket error: "+e};